// Ported from the Node app's Sequelize model LoginEvent (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class LoginEventConfiguration : IEntityTypeConfiguration<LoginEvent>
{
    public void Configure(EntityTypeBuilder<LoginEvent> builder)
    {
        builder.ToTable("login_events");
        builder.ConfigureAudit();
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.UserId).HasColumnName("user_id");
        builder.Property(e => e.Email).HasColumnName("email").HasColumnType("nvarchar(150)").HasMaxLength(150).IsRequired();
        builder.Property(e => e.Role).HasColumnName("role").HasColumnType("nvarchar(20)").HasMaxLength(20);
        builder.Property(e => e.Success).HasColumnName("success");
        builder.Property(e => e.Ip).HasColumnName("ip").HasColumnType("nvarchar(64)").HasMaxLength(64);
        builder.Property(e => e.UserAgent).HasColumnName("user_agent").HasColumnType("nvarchar(200)").HasMaxLength(200);
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("datetime2");
        builder.HasIndex(e => e.CreatedAt).HasDatabaseName("ix_login_events_created");
        builder.HasIndex(e => new { e.UserId, e.CreatedAt }).HasDatabaseName("ix_login_events_user");
    }
}
